<script setup>
import {s,dateText} from './store';
defineProps({open:Boolean});
const time=v=>v?new Date(v).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}):'—';
</script><template><div v-if="open||s.filters.snapshot||Object.keys(s.sources).length||s.filters.from||s.filters.to||s.refreshWarning||s.event.sync_error||s.report?.current.invalidDates" class="report-stamp"><div v-if="open" id="report-metadata" class="card stack"><p class="muted">Tổng hợp lúc {{time(s.report?.generatedAt)}}</p><p class="muted">{{!s.filters.from&&!s.filters.to?'Toàn bộ thời gian đã nhập':'Thời gian submit: '+(s.filters.from?dateText(s.filters.from):'Từ đầu')+' → '+(s.filters.to?dateText(s.filters.to):'Mới nhất')}}</p><p class="muted">Nguyên tắc lọc trùng: {{({none:'Không lọc trùng',email:'Email',phone:'Số điện thoại'})[s.event.settings.dedup]}}. Dòng thiếu thông tin dùng để lọc trùng vẫn được giữ.</p><p v-if="s.event.source" class="muted">{{s.event.source.enabled?'Tự cập nhật Google Sheet':'Đồng bộ đang tắt'}} · Kiểm tra nguồn: {{time(s.event.synced_at)}}</p></div>
<p v-if="s.filters.snapshot" class="muted">Đang xem phiên lịch sử đã chọn.</p><p v-if="Object.keys(s.sources).length||s.filters.from||s.filters.to" class="muted">{{s.filters.from?dateText(s.filters.from):'Từ đầu'}} → {{s.filters.to?dateText(s.filters.to):'Mới nhất'}}<span v-for="(v,k) in s.sources" :key="k"> · {{k}}: {{v||'Chưa xác định'}}</span></p>
<p v-if="s.refreshWarning||s.event.sync_error" class="notice" role="status">{{s.refreshWarning||s.event.sync_error}} Đang giữ dữ liệu đã nhập gần nhất.</p><p v-if="s.report?.current.invalidDates" class="notice">{{s.report.current.invalidDates}} dòng chưa có ngày hợp lệ: được tính khi xem toàn bộ, không nằm trong bộ lọc ngày.</p>
</div></template>
